D = [
dict(case="Lichen sclerosus et atrophicus", src=f"{PYQ}; {IA} (Lichen sclerosus)",
 qa=[
 ("What is lichen sclerosus (LS)?", ["Chronic inflammatory, scarring, lymphocyte-mediated dermatosis with a strong predilection for anogenital skin; bimodal in women (prepubertal girls and post-menopausal women); in men mostly uncircumcised adults (balanitis xerotica obliterans)", "Associated autoimmunity (thyroid, vitiligo, alopecia areata; antibodies to extracellular matrix protein 1 — ECM1), Koebner, occlusion by urine in uncircumcised males"]),
 ("Clinical features in women.", ["Itch (often severe, nocturnal), soreness, dyspareunia, dysuria, constipation in girls", "Porcelain-white atrophic shiny plaques with cigarette-paper wrinkling, purpura/ecchymoses, erosions, fissures in a 'figure-of-eight' around vulva and anus", "Scarring: resorption of labia minora, burying of clitoris (phimosis of clitoral hood), narrowing of introitus; vagina is spared (unlike LP)"]),
 ("Clinical features in men.", ["Whitish sclerotic ring on prepuce, glans, coronal sulcus; phimosis (commonest cause of acquired phimosis), meatal stenosis, urethral stricture, painful erections; perianal involvement rare in men"]),
 ("Extragenital LS.", ["~15–20%: white polygonal flat papules coalescing into atrophic plaques with follicular plugging (delling) on trunk, neck, upper arms, under breasts; usually not itchy; does not carry SCC risk"]),
 ("Histopathology.", ["Hyperkeratosis with follicular plugging, epidermal atrophy, basal vacuolar change, broad band of homogenised pale oedematous collagen in the upper dermis (hyalinisation), beneath which a band-like lymphocytic infiltrate"]),
 ("Differential diagnosis.", ["Vitiligo (no atrophy/scarring), lichen planus (erosive — vagina involved, Wickham's striae), morphoea (LS–morphoea overlap), mucous membrane pemphigoid (scarring), VIN/ differentiated VIN, extramammary Paget's, child sexual abuse (girls — LS purpura misinterpreted as trauma), lichen simplex, candidiasis"]),
 ("What is the malignancy risk?", ["Vulval SCC in ~3–5% of untreated anogenital LS (differentiated VIN pathway, HPV-independent); penile SCC risk also raised; reduced by adequate long-term potent topical steroid therapy", "Lifelong follow-up; biopsy persistent ulcers, thickened, hyperkeratotic or non-responding areas"]),
 ("Management.", ["Super-potent topical steroid — clobetasol propionate 0.05% ointment once daily for 4 weeks, alternate days for 4 weeks, twice weekly for 4 weeks, then maintenance 1–2 times weekly long-term (30 g tube lasts ~3 months)", "Emollients/soap substitutes; avoid irritants; topical tacrolimus/pimecrolimus as second line", "Men: circumcision is often curative for penile LS (with steroids); meatal dilatation/urethroplasty for strictures", "Refractory: intralesional steroids, acitretin, PDT, fractional CO2 laser, PRP/fat grafting (experimental)", "Girls: improves around puberty in some but may persist — continue treatment"]),
 ],
 spot=["Porcelain-white figure-of-eight atrophy around vulva and anus — LS", "Phimosis in adult male — balanitis xerotica obliterans", "Clobetasol ointment, lifelong follow-up for SCC"]),

dict(case="Morphea (localised scleroderma)", src=f"{PYQ}; {IA} (Morphoea); Padua consensus classification",
 qa=[
 ("Define morphoea.", ["Localised scleroderma — inflammatory sclerosing disease of the skin and underlying tissues (fat, fascia, muscle, bone) without Raynaud's, sclerodactyly or internal organ involvement; does not progress to systemic sclerosis"]),
 ("Classify morphoea (Padua / Laxer–Zulian classification).", ["Circumscribed (plaque) — superficial or deep (morphoea profunda)", "Linear — trunk/limbs, or head (en coup de sabre, progressive hemifacial atrophy/Parry–Romberg)", "Generalised — ≥4 plaques >3 cm in ≥2 of 7 anatomical sites; includes isomorphic/symmetric types", "Pansclerotic — circumferential involvement of limbs including bone, children, risk of SCC in ulcers", "Mixed (e.g. linear + circumscribed)", "Others: guttate, keloidal/nodular, bullous, atrophoderma of Pasini and Pierini, eosinophilic fasciitis (Shulman) — related"]),
 ("Clinical features of plaque morphoea.", ["Oval indurated plaques with ivory-white shiny centre and a violaceous/lilac border (active inflammation — 'lilac ring'); later hyper- or hypopigmented atrophic patches with loss of hair and sweating", "Trunk (bra-line, waist), proximal limbs"]),
 ("Linear morphoea — why important in children?", ["Commonest type in children; along a limb, may cross joints → contractures, limb-length discrepancy, muscle atrophy, growth failure", "En coup de sabre (frontoparietal 'sword-cut' depression of scalp/forehead with scarring alopecia) — may have neurological (seizures, headache) and ocular involvement", "Needs early systemic therapy (methotrexate) and physiotherapy"]),
 ("Pathogenesis.", ["Unknown: endothelial injury and inflammation (Th1/Th17 early, Th2 later) → TGF-β-driven fibroblast activation and collagen deposition", "Triggers: trauma (Koebner), radiation (post-radiation morphoea of breast), infections (Borrelia burgdorferi in Europe — debated), drugs, vaccinations; autoimmune association (ANA, anti-ssDNA, anti-histone in linear/generalised)"]),
 ("Investigations.", ["Clinical diagnosis; biopsy (deep incisional) if doubt", "ANA, anti-ssDNA, anti-histone (correlate with deep/active linear disease), eosinophilia (in eosinophilic fasciitis), CBC", "MRI (deep tissue/brain in en coup de sabre), ultrasound and thermography for activity; LoSCAT (localised scleroderma cutaneous assessment tool — mLoSSI activity and LoSDI damage)"]),
 ("Histopathology.", ["Early (inflammatory): perivascular and interstitial lymphoplasmacytic infiltrate at dermal–subcutaneous junction, swollen collagen", "Late (sclerotic): thick hyalinised collagen bundles parallel to the surface throughout dermis, loss of adnexa (trapped eccrine glands without surrounding fat), square 'punch biopsy' sign, reduced CD34 dendritic cells"]),
 ("Differential diagnosis.", ["Systemic sclerosis (Raynaud's, sclerodactyly), lichen sclerosus (overlap), post-inflammatory pigmentation, vitiligo, scleredema, lipoatrophy (steroid injection), necrobiosis lipoidica, eosinophilic fasciitis (groove sign, peau d'orange, eosinophilia), radiation fibrosis, morphoeic BCC, nephrogenic systemic fibrosis"]),
 ("Management.", ["Limited plaque disease: potent topical steroids, tacrolimus, calcipotriol (± betamethasone), imiquimod; intralesional steroid for active border", "Phototherapy: UVA1 (medium dose) or PUVA/bath PUVA for widespread plaques; NB-UVB for superficial", "Systemic (linear, generalised, pansclerotic, deep, functionally threatening, en coup de sabre): methotrexate 15 mg/m²/week (max 25 mg) + systemic corticosteroids (pulse IV methylprednisolone or oral) for 3 months, continue MTX ≥12–24 months; mycophenolate if MTX fails; tocilizumab, abatacept, JAK inhibitors for refractory", "Physiotherapy for contractures; surgical correction/fat grafting for atrophy once inactive"]),
 ("Prognosis.", ["Plaque morphoea usually softens over 3–5 years leaving pigmentation; linear and deep forms cause lasting deformity; relapse in ~25–30% (especially childhood linear)"]),
 ],
 spot=["Ivory-white indurated plaque with lilac ring — morphoea", "En coup de sabre — linear morphoea on forehead", "Methotrexate + steroids for linear disease"]),

dict(case="Parry–Romberg syndrome", src=f"{PYQ}; {IA} (Morphoea — progressive hemifacial atrophy)",
 qa=[
 ("What is Parry–Romberg syndrome? (PYQ)", ["Progressive hemifacial atrophy — slowly progressive, usually unilateral atrophy of the skin, subcutaneous fat, muscle and bone of the face, typically in the distribution of one or more branches of the trigeminal nerve; considered part of the linear morphoea spectrum (often coexists with en coup de sabre)"]),
 ("Clinical features.", ["Onset in childhood/adolescence (first or second decade), females more", "Progressive sinking of one side of face — cheek, temple, around eye (enophthalmos), lip, tongue, gums; minimal skin induration (unlike en coup de sabre), sometimes hyperpigmentation; deviation of mouth and nose to affected side", "Progression for 2–10 years then 'burns out'", "Associated: ipsilateral hair loss/whitening, heterochromia of iris, uveitis, dental root atrophy, delayed eruption, trigeminal neuralgia, facial pain, migraine, seizures (with intracranial calcification or white-matter lesions on MRI)"]),
 ("How do you differentiate it from en coup de sabre?", ["En coup de sabre: paramedian forehead/frontal scalp linear band, sclerotic/indurated skin, scarring alopecia", "Parry–Romberg: lower face (below forehead), atrophy of deeper tissues predominantly with little skin sclerosis", "Both may coexist and share neurological complications"]),
 ("Investigations.", ["MRI brain (ipsilateral white-matter hyperintensities, calcification, atrophy) and EEG if neurological symptoms; ophthalmology review", "Facial imaging (CT/MRI) to assess bone/fat loss; photographs and measurements to track progression", "ANA, anti-ssDNA (may be positive)"]),
 ("Differential diagnosis.", ["Linear morphoea/en coup de sabre, facial lipodystrophy (HIV/acquired partial lipodystrophy — bilateral), Rasmussen encephalitis, lupus profundus, hemifacial microsomia (congenital, non-progressive), steroid-induced lipoatrophy, Barraquer–Simons syndrome (bilateral, cephalocaudal)"]),
 ("Management.", ["Active phase: methotrexate with systemic corticosteroids (pulse methylprednisolone) as in linear morphoea; mycophenolate; hydroxychloroquine (adjunct)", "After disease is inactive (≥1–2 years stable): reconstructive surgery — autologous fat grafting (most common), dermal fillers (hyaluronic acid), free flaps, bone grafts/implants; orthodontic and dental care", "Antiepileptics for seizures; eye care"]),
 ("Prognosis.", ["Self-limiting progression with permanent facial asymmetry; psychosocial impact large"]),
 ],
 spot=["Unilateral progressive facial sinking in a child without much skin sclerosis — Parry–Romberg", "Treat active phase like linear morphoea; reconstruct after burnout"]),

dict(case="Striae distensae", src=f"{PYQ}; {IA} (Dermal disorders; physiological skin changes in pregnancy)",
 qa=[
 ("What are striae distensae?", ["Linear dermal scars with epidermal atrophy due to stretching and changes in dermal connective tissue (stretch marks)", "Early: striae rubrae (red/purple, raised, inflamed); late: striae albae (white, atrophic, wrinkled, depressed)"]),
 ("Causes.", ["Physiological: puberty (adolescent growth spurt — thighs, buttocks, breasts, lower back), pregnancy (striae gravidarum — up to 90%, abdomen, breasts, thighs; PYQ in physiological changes of pregnancy), weight gain/obesity, body-building", "Pathological: Cushing's syndrome (wide >1 cm, purple, also on unusual sites), prolonged topical or systemic corticosteroids (especially potent steroids under occlusion in flexures — groin, axilla, inner thighs), Marfan syndrome, Ehlers–Danlos, anorexia nervosa recovery, chronic liver disease, HIV (protease inhibitors), diabetes"]),
 ("Pathogenesis.", ["Mechanical stretch + hormonal influence (glucocorticoids, oestrogen, relaxin) → fibroblast dysfunction, fragmentation and loss of elastic fibres and fibrillin, reduced collagen synthesis → rupture of dermal connective tissue", "Genetic predisposition (family history, fibrillin/elastin/collagen gene variants)"]),
 ("Histopathology.", ["Early: dermal oedema, perivascular lymphocytes, elastolysis", "Late: thinned epidermis with flattened rete ridges, thin straight collagen bundles parallel to skin surface (like a scar), reduced and curled elastic fibres, loss of adnexa"]),
 ("Differential diagnosis.", ["Linear focal elastosis (yellow palpable striae on lower back of elderly men), anetoderma, atrophic scars, linear atrophoderma of Moulin, linear morphoea", "Cushing's striae vs physiological: wide, deep purple, beyond usual sites (shoulders, axillae), with other Cushingoid features — screen with cortisol tests"]),
 ("Treatment.", ["Prevention: no strong evidence; massage with emollients (centella asiatica, hyaluronic acid) may help in pregnancy", "Striae rubrae respond better: topical tretinoin 0.05–0.1% (not in pregnancy/lactation), hyaluronic acid, pulsed-dye laser 585/595 nm, IPL", "Striae albae: microneedling (± PRP), fractional non-ablative (1550 nm) or ablative (CO2, Er:YAG) lasers, radiofrequency, microdermabrasion, excimer laser (repigmentation), chemical peels (glycolic/TCA)", "Counsel: improvement (not complete removal) is the realistic goal; treat cause (stop steroids, Cushing's)"]),
 ],
 spot=["Wide purple striae on unusual sites — think Cushing's/steroids", "Striae rubrae respond better than striae albae"]),

dict(case="Granuloma annulare", src=f"{PYQ}; {IA} (Non-infectious granulomas)",
 qa=[
 ("What is granuloma annulare (GA)?", ["Benign, usually self-limiting, non-infectious granulomatous dermatosis with annular arrangement of smooth papules; children and young adults (localised), middle-aged women (generalised)"]),
 ("Clinical variants.", ["Localised (commonest — dorsa of hands/feet, fingers, ankles; skin-coloured to pink beaded papules in a ring without scale; central skin normal or slightly violaceous)", "Generalised/disseminated (≥10 lesions on trunk and limbs; adults; associations — diabetes, dyslipidaemia, thyroid disease, HIV, malignancy (lymphoma) in some; chronic)", "Subcutaneous (deep nodules on shins, scalp, hands of children — 'pseudo-rheumatoid nodules')", "Perforating (umbilicated papules with central crust — hands)", "Patch/macular (erythematous patches — 'interstitial GA'), micropapular, actinic (photo-exposed — annular elastolytic giant cell granuloma), drug-induced (TNF inhibitors, allopurinol, ACE inhibitors)"]),
 ("Pathogenesis.", ["Unknown — delayed-type hypersensitivity reaction to an unknown antigen with collagen degeneration (necrobiosis) and mucin; triggers: insect bites, trauma, tuberculin test, vaccines, sun, viral infections, drugs; Th1 cells, TNF-α, JAK-STAT signalling (basis for JAK inhibitors)"]),
 ("Histopathology.", ["Palisading granuloma: central zone of altered (necrobiotic) collagen with abundant mucin surrounded by palisading histiocytes and lymphocytes in upper/mid dermis", "Interstitial pattern: histiocytes scattered between collagen bundles with mucin ('busy dermis')", "Mucin (Alcian blue/colloidal iron) differentiates from necrobiosis lipoidica (little mucin, layered 'cake' pattern, plasma cells) and rheumatoid nodule (fibrinoid necrosis, deeper)"]),
 ("Differential diagnosis of annular plaques.", ["Tinea corporis (scaly active edge, KOH), annular lichen planus (violaceous, Wickham's striae), tuberculoid/borderline-tuberculoid leprosy (anaesthesia, nerve), sarcoidosis (annular), necrobiosis lipoidica (shins, yellow atrophic), erythema annulare centrifugum (trailing scale), SCLE, secondary syphilis (annular), mycosis fungoides, actinic GA, porokeratosis (keratotic ridge)"]),
 ("Investigations.", ["Clinical ± biopsy; in generalised GA: blood sugar/HbA1c, lipid profile, thyroid function, HIV, hepatitis; consider malignancy screen if atypical in elderly"]),
 ("Treatment.", ["Localised: reassurance (50% resolve within 2 years), potent topical steroid under occlusion, intralesional triamcinolone (2.5–5 mg/ml), cryotherapy, tacrolimus; 'biopsy-induced resolution' is described", "Generalised: phototherapy (PUVA, NB-UVB, UVA1), hydroxychloroquine, dapsone, isotretinoin, doxycycline/minocycline + rifampicin + ofloxacin ('ROM' monthly combination), pentoxifylline, methotrexate, TNF inhibitors (paradoxical GA reported too), JAK inhibitors (tofacitinib) for refractory", "Treat associated diabetes/dyslipidaemia"]),
 ("Prognosis.", ["Localised GA resolves spontaneously in ~50% within 2 years without scars but recurs in ~40% (often at same site); generalised GA more chronic and resistant"]),
 ],
 spot=["Ring of smooth skin-coloured beaded papules on dorsa of hands, no scale — GA", "Palisading granuloma with mucin"]),

dict(case="Dermatitis artefacta", src=f"{PYQ}; {IA} (Psychocutaneous disorders)",
 qa=[
 ("Classify psychocutaneous disorders (PYQ).", ["Psychophysiological disorders — skin disease worsened by stress (psoriasis, atopic dermatitis, urticaria, acne, alopecia areata, hyperhidrosis)", "Primary psychiatric disorders with skin manifestations — dermatitis artefacta (factitious disorder), delusional infestation (delusional parasitosis), body dysmorphic disorder, trichotillomania, skin picking (excoriation) disorder, neurotic excoriations, acne excoriée, onychophagia, dysmorphophobia, Dhat syndrome", "Secondary psychiatric disorders due to skin disease — depression, anxiety, social phobia (vitiligo, psoriasis, acne, alopecia)", "Cutaneous sensory disorders — glossodynia, vulvodynia, scalp dysaesthesia, chronic pruritus without cause", "Skin side-effects of psychotropic drugs (lithium acne/psoriasis, anticonvulsant SJS, antipsychotic pigmentation)"]),
 ("Define dermatitis artefacta (PYQ).", ["Self-inflicted skin lesions produced consciously but with motivation that is unconscious (need for care, attention, escape from stress) — the patient denies self-infliction; a factitious disorder (not malingering, where there is conscious external gain)", "Commonest in adolescent girls and young women; often with borderline personality traits, past trauma/abuse, stress, health-care workers"]),
 ("Clinical clues.", ["'Hollow history' — lesions appear fully formed overnight, vague account, patient unconcerned (la belle indifférence) while family anxious", "Bizarre geometric shapes, straight lines, sharp angulated margins, normal surrounding skin, within reach of the dominant hand (spares the hand used, mid-back spared), unilateral, symmetrical patterns", "Lesion types: excoriations, burns (cigarette, chemical — drip marks), ulcers, purpura (suction, ligature), blisters, panniculitis (injection of foreign material — milk, faeces, oil), dermatitis from caustics, hair pulling, eyelid/lip lesions", "Failure to heal with standard therapy; healing under occlusive dressing (e.g. plaster cast) — diagnostic"]),
 ("How do you differentiate dermatitis artefacta, malingering and neurotic excoriations?", ["Artefacta: unconscious motive, denies self-infliction", "Malingering: conscious production for external gain (compensation, avoid work/prison)", "Neurotic excoriations/skin picking: patient admits picking (compulsion), lesions in reachable areas, repeated picking of normal skin or minor bumps"]),
 ("Differential diagnosis.", ["Vasculitis, pyoderma gangrenosum (pathergy — surgery worsens), contact dermatitis, porphyria, bullous diseases, infections (ecthyma, atypical mycobacteria), panniculitis, Munchausen syndrome by proxy (child), child abuse/non-accidental injury"]),
 ("Investigations.", ["Mainly clinical and to exclude organic disease: biopsy (foreign-body granuloma, polarisable material), cultures, patch test; occlusion test (healing under sealed dressing)", "Psychological assessment"]),
 ("Management.", ["Non-confrontational, empathetic, long-term relationship with the patient — avoid accusing directly; acknowledge distress", "Symptomatic wound care, occlusive dressings, treat infection", "Joint dermatology–psychiatry (psychodermatology) care: psychotherapy (CBT, dialectical behaviour therapy), treat underlying depression/anxiety/personality disorder — SSRIs, low-dose antipsychotics", "Avoid unnecessary investigations/surgeries; involve family carefully; safeguarding in children"]),
 ("Write short notes on delusional infestation (PYQ).", ["Fixed false belief of being infested by parasites/organisms despite no evidence; middle-aged/elderly women; 'matchbox sign' (bringing specimens — lint, skin debris)", "Primary (monosymptomatic hypochondriacal psychosis) or secondary (schizophrenia, depression, dementia, drugs — cocaine, amphetamines, dopamine agonists; organic — B12 deficiency, hypothyroidism, renal failure)", "Treatment: build trust, exclude real infestation and organic causes, antipsychotics — risperidone, olanzapine, aripiprazole, (pimozide — older, QT prolongation)"]),
 ],
 spot=["Bizarre geometric lesions within reach of the dominant hand, 'hollow history' — dermatitis artefacta", "Heals under occlusion"]),

dict(case="Recurrent aphthous stomatitis", src=f"{PYQ}; {IA} (Oral mucosal disorders)",
 qa=[
 ("Define recurrent aphthous stomatitis (RAS).", ["Commonest oral mucosal disease: recurrent, painful, round/oval ulcers with a yellow-grey fibrinous base and erythematous halo on non-keratinised mucosa, in otherwise healthy people; affects ~20% of population; starts in childhood/adolescence"]),
 ("Classify RAS.", ["Minor (Mikulicz) aphthae ~80%: <1 cm, 1–5 ulcers, heal in 7–14 days without scar", "Major (Sutton's, periadenitis mucosa necrotica recurrens) ~10%: >1 cm, deep, last 2–6 weeks, heal with scarring, can involve soft palate, fauces, tongue", "Herpetiform ~10%: crops of 10–100 pinpoint ulcers that coalesce, heal in 1–2 weeks; not caused by HSV", "Simple vs complex aphthosis (almost constant ulcers — look for systemic disease)"]),
 ("Aetiology / precipitating factors.", ["Genetic predisposition (family history), local trauma (brushing, dental appliances), stress, hormonal (luteal phase), smoking cessation, food hypersensitivity (chocolate, nuts, tomato, cinnamon), sodium lauryl sulphate toothpaste", "Nutritional deficiencies: iron, vitamin B12, folate, zinc, vitamin D", "Systemic associations (aphthous-like ulcers): Behçet's disease, coeliac disease, Crohn's disease/UC, HIV, cyclic neutropenia, PFAPA (periodic fever, aphthous stomatitis, pharyngitis, adenitis), MAGIC syndrome, Sweet syndrome, drugs (NSAIDs, nicorandil, methotrexate, beta-blockers, mTOR inhibitors)"]),
 ("Differential diagnosis of oral ulcers.", ["Herpetic stomatitis/recurrent intraoral herpes (keratinised mucosa — hard palate, gums; vesicles first)", "Hand-foot-mouth disease, herpangina, traumatic ulcer, Behçet's disease, pemphigus vulgaris, mucous membrane pemphigoid, erosive LP, EM/SJS, SLE (palatal, painless), tuberculosis, syphilis, deep fungal, SCC (persistent, indurated — biopsy any ulcer >3 weeks), drug (nicorandil), neutropenia, agranulocytosis"]),
 ("What is Behçet's disease? Criteria.", ["Variable-vessel vasculitis along the old Silk Road (Turkey, Middle East, Japan); HLA-B51", "International Criteria for Behçet's Disease (ICBD 2014): oral aphthosis 2, genital aphthosis 2, ocular lesions (uveitis, retinal vasculitis) 2, skin lesions (pseudofolliculitis, erythema nodosum) 1, neurological 1, vascular (thrombosis, aneurysm) 1, positive pathergy test 1 — ≥4 points = Behçet's", "Pathergy test: 20–22 G needle prick on forearm → papule/pustule at 48 h", "Treatment: colchicine, topical steroids, apremilast (oral ulcers), azathioprine, TNF inhibitors (eye, vascular, neuro), interferon-α"]),
 ("Investigations in recurrent/complex aphthae.", ["CBC, serum ferritin, B12, folate, zinc, vitamin D; coeliac serology (tTG-IgA), HIV; stool/endoscopy if GI symptoms; serial neutrophil counts for cyclic neutropenia; biopsy for atypical/persistent ulcers; pathergy and eye exam if Behçet's suspected"]),
 ("Treatment.", ["Avoid triggers (SLS toothpaste, trauma, offending foods); correct deficiencies", "Topical: corticosteroids (triamcinolone in orabase, clobetasol gel, betamethasone mouthwash, beclomethasone spray), anaesthetics (lignocaine gel, benzydamine), antiseptics (chlorhexidine 0.2%), tetracycline/doxycycline mouthwash (herpetiform), amlexanox, sucralfate, hyaluronic acid gel", "Systemic (severe/major/complex): colchicine 0.5–1.5 mg/day, dapsone, pentoxifylline, short prednisolone course, apremilast, thalidomide (major aphthae in HIV — teratogenic, neuropathy), TNF inhibitors for refractory/ Behçet's", "Laser (low-level/CO2) for pain relief"]),
 ("Prognosis.", ["Minor aphthae become less frequent with age; major aphthae chronic; look for systemic disease when ulcers are complex or start in adulthood"]),
 ],
 spot=["Round shallow yellow-based ulcers with red halo on non-keratinised mucosa — aphthae", "Oral + genital ulcers + uveitis + pathergy — Behçet's", "Any oral ulcer >3 weeks — biopsy"]),
]
